#pragma once

#include <omni/log/ILog.h>
#include <chrono>
#include <atomic>

namespace omni
{

/**
 * @brief Basic time-based throttler for any repeated operation
 * 
 * Throttles repeated calls to an invocable object based on elapsed time.
 * The invocable is always called on the first invocation, then only called again
 * after the specified delay has elapsed since the last invocation.
 * 
 * @tparam DelayType Duration type for throttling (e.g., std::chrono::milliseconds)
 * 
 * @example
 * ```cpp
 * Throttler<std::chrono::seconds> throttler(std::chrono::seconds(5));
 * 
 * // In a frequently-called loop:
 * throttler.invoke([](auto elapsedSinceFirst) {
 *     printf("Been running for %lld seconds\n", elapsedSinceFirst.count());
 * });
 * ```
 */
template <typename DelayType = std::chrono::seconds>
class Throttler
{
public:
    explicit Throttler(DelayType delay) : m_delay(std::move(delay))
    {
    }

    /**
     * @brief Invoke the function with throttling
     * 
     * The function receives the elapsed time since the first invocation.
     * 
     * @tparam FN_T Callable type - must accept a DelayType parameter
     * @param fn Function to invoke (receives elapsed time since first call)
     */
    template <typename FN_T>
    void invoke(FN_T&& fn)
    {
        const auto now = std::chrono::steady_clock::now();
        bool shouldExec = false;
        if (m_isFirstInvocation)
        {
            m_isFirstInvocation = false;
            m_first = now;
            m_previous = now;
            shouldExec = true;
        }
        else
        {
            shouldExec = ((now - m_previous) >= m_delay);
        }

        if (shouldExec)
        {
            std::forward<FN_T>(fn)(now - m_first);
            m_previous = now;
        }
    }

    /**
     * @brief Get total elapsed time since first invocation
     * 
     * @return Elapsed time in DelayType units, or 0 if never invoked
     */
    DelayType getElapsedTime() const
    {
        if (m_isFirstInvocation)
        {
            return DelayType{ 0 };
        }
        else
        {
            return std::chrono::duration_cast<DelayType>(std::chrono::steady_clock::now() - m_first);
        }
    }

private:
    bool m_isFirstInvocation = true;
    DelayType m_delay;
    std::chrono::time_point<std::chrono::steady_clock> m_first;
    std::chrono::time_point<std::chrono::steady_clock> m_previous;
};

/**
 * @brief Log throttler with verbosity-aware behavior
 * 
 * This throttler adjusts its behavior based on whether a log channel is enabled
 * at a certain verbosity level:
 * 
 * - If the channel is enabled at `defaultLogLevel`: logs are emitted on every invocation
 * - Otherwise: logs are throttled according to `logThrottleDelay` and emitted at `throttledLogLevel`
 * 
 * This is useful for providing detailed logs when users explicitly enable verbose logging,
 * while avoiding log spam in production scenarios.
 * 
 * @tparam DelayType Duration type for throttling (e.g., std::chrono::milliseconds)
 * 
 * @example
 * ```cpp
 * LogThrottlerWithVerbosity<std::chrono::milliseconds> throttler(
 *     myLogChannel,
 *     omni::log::Level::eVerbose,     // If verbose is enabled, log everything
 *     omni::log::Level::eInfo,        // Otherwise, throttle at info level
 *     std::chrono::milliseconds(5000) // Throttle to once per 5 seconds
 * );
 * 
 * // In a loop or frequently-called code:
 * throttler.invoke([](omni::log::Level level, uint32_t elapsedMs) {
 *     OMNI_LOG_WRITE(myChannel, level, "Progress: %u ms elapsed", elapsedMs);
 * });
 * ```
 */
template <typename DelayType = std::chrono::milliseconds>
class LogThrottlerWithVerbosity
{
public:
    /**
     * @brief Construct a log throttler with verbosity-based behavior
     * 
     * @param channel The log channel to check for verbosity
     * @param defaultLogLevel The log level to check - if enabled, don't throttle
     * @param throttledLogLevel The log level to use when throttling
     * @param logThrottleDelay Minimum time between throttled log messages
     */
    LogThrottlerWithVerbosity(const omni::log::LogChannelData& channel,
                              omni::log::Level defaultLogLevel,
                              omni::log::Level throttledLogLevel,
                              DelayType logThrottleDelay)
        : m_channel(channel),
          m_defaultLogLevel(defaultLogLevel),
          m_throttledLogLevel(throttledLogLevel),
          m_logThrottler(logThrottleDelay),
          m_creationTime(std::chrono::steady_clock::now())
    {
    }

    /**
     * @brief Invoke the logging lambda with appropriate throttling
     * 
     * The lambda receives:
     * - The log level to use (either default or throttled)
     * - Elapsed time in DelayType units since throttler creation
     * 
     * @tparam Lambda Callable with signature: void(omni::log::Level, uint32_t elapsedTime)
     * @param lambda The logging function to invoke
     */
    template <typename Lambda>
    void invoke(Lambda&& lambda)
    {
        // If the default logging level is enabled, output the message at every invocation
        if (omni::log::detail::isChannelEnabled(m_defaultLogLevel, m_channel))
        {
            lambda(m_defaultLogLevel, uint32_t(getElapsedTime().count()));
        }
        // Otherwise throttle
        else
        {
            m_logThrottler.invoke([this, lambda](auto elapsedSinceFirstLog)
                                  { lambda(m_throttledLogLevel, uint32_t(getElapsedTime().count())); });
        }
    }

    /**
     * @brief Get elapsed time since throttler creation
     * 
     * @return Elapsed time in DelayType units
     */
    DelayType getElapsedTime() const
    {
        return std::chrono::duration_cast<DelayType>(std::chrono::steady_clock::now() - m_creationTime);
    }

private:
    const omni::log::LogChannelData& m_channel;
    omni::log::Level m_defaultLogLevel;
    omni::log::Level m_throttledLogLevel;
    Throttler<DelayType> m_logThrottler;
    std::chrono::time_point<std::chrono::steady_clock> m_creationTime;
};

} // namespace omni
